          reason "native_dependency:company_book_transition_v1.py";
        end;
      end;
      stages;
        stage;
          id "envelope";
          op record_fields;
          reason "exact_normalized_state_fields";
          path [];
          fields ["profile","opening","memory_definition","schemas","roles","unit_cost_pointer","migration"];
        end;
        stage;
          id "profile";
          op equals;
          reason "term_state_profile";
          path ["profile"];
          value "ReceivableTermHistory/1";
        end;
        stage;
          id "typed_book";
          op typed_book;
          reason "typed_book";
        end;
        stage;
          id "claim_shape";
          op map_values;
          reason "term_claim_type";
          path ["memory_definition","root","fields","claims"];
          values {"node":"record","fields":{"customer":{"node":"scalar","type":{"kind":"text","context":{}}},"due":{"node":"scalar","type":{"kind":"date","context":{}}},"issued":{"node":"scalar","type":{"kind":"date","context":{}}},"sale_event":{"node":"scalar","type":{"kind":"text","context":{}}},"remaining":{"node":"scalar","type":{"kind":"rational","context":{"entity":"Operating-beta","book":"legal-beta","case_id":"synthetic-cycle-beta","mode":"synthetic"},"dimensions":{"currency:USD":1},"scale":"1/1"}},"assessed":{"node":"scalar","type":{"kind":"boolean","context":{}}},"assessment_date":{"node":"scalar","type":{"kind":"date","context":{}}},"assessed_remaining":{"node":"scalar","type":{"kind":"rational","context":{"entity":"Operating-beta","book":"legal-beta","case_id":"synthetic-cycle-beta","mode":"synthetic"},"dimensions":{"currency:USD":1},"scale":"1/1"}},"overdue":{"node":"scalar","type":{"kind":"rational","context":{"entity":"Operating-beta","book":"legal-beta","case_id":"synthetic-cycle-beta","mode":"synthetic"},"dimensions":{"currency:USD":1},"scale":"1/1"}},"current_term":{"node":"scalar","type":{"kind":"text","context":{}}},"latest_assessment":{"node":"scalar","type":{"kind":"text","context":{}}},"terms":{"node":"map","max_items":32,"values":{"node":"record","fields":{"due":{"node":"scalar","type":{"kind":"date","context":{}}},"effective":{"node":"scalar","type":{"kind":"date","context":{}}},"event_id":{"node":"scalar","type":{"kind":"text","context":{}}},"predecessor":{"node":"scalar","type":{"kind":"text","context":{}}},"premise":{"node":"scalar","type":{"kind":"text","context":{}}}}}},"assessments":{"node":"map","max_items":64,"values":{"node":"record","fields":{"term_id":{"node":"scalar","type":{"kind":"text","context":{}}},"as_of":{"node":"scalar","type":{"kind":"date","context":{}}},"remaining":{"node":"scalar","type":{"kind":"rational","context":{"entity":"Operating-beta","book":"legal-beta","case_id":"synthetic-cycle-beta","mode":"synthetic"},"dimensions":{"currency:USD":1},"scale":"1/1"}},"overdue":{"node":"scalar","type":{"kind":"rational","context":{"entity":"Operating-beta","book":"legal-beta","case_id":"synthetic-cycle-beta","mode":"synthetic"},"dimensions":{"currency:USD":1},"scale":"1/1"}},"origin":{"node":"scalar","type":{"kind":"text","context":{}}},"event_id":{"node":"scalar","type":{"kind":"text","context":{}}}}}}}};
        end;
        stage;
          id "clock_shape";
          op equals;
          reason "term_clock_type";
          path ["memory_definition","root","fields","collection_clock"];
          value {"node":"record","fields":{"cursor":{"node":"scalar","type":{"kind":"date","context":{}}}}};
        end;
        stage;
          id "roles";
          op role_population;
          reason "complete_operating_roles";
          roles ["cash","receivables","inventory","payables","payroll_payable","revenue","cost_of_sales","payroll"];
        end;
        stage;
          id "roles_injective";
          op role_injective;
          reason "injective_operating_roles";
        end;
        stage;
          id "role_classes";
          op role_classes;
          reason "operating_role_class:";
          classes;
            class;
              role "cash";
              classification "asset";
            end;
            class;
              role "receivables";
              classification "asset";
            end;
            class;
              role "inventory";
              classification "asset";
            end;
            class;
              role "payables";
              classification "liability";
            end;
            class;
              role "payroll_payable";
              classification "liability";
            end;
            class;
              role "revenue";
              classification "income";
            end;
            class;
              role "cost_of_sales";
              classification "expense";
            end;
            class;
              role "payroll";
              classification "expense";
            end;
          end;
        end;
        stage;
          id "cash_role";
          op cash_role;
          reason "operating_cash_role";
          role "cash";
        end;
        stage;
          id "cost_leaf";
          op memory_leaf;
          reason "unit_cost_leaf";
        end;
        stage;
          id "cost_type";
          op memory_type;
          reason "unit_cost_dimensions";
          type {"kind":"rational","context":{"entity":"Operating-beta","book":"legal-beta","case_id":"synthetic-cycle-beta","mode":"synthetic"},"dimensions":{"currency:USD":1,"goods:unit":-1},"scale":"1/1"};
        end;
        stage;
          id "positive_cost";
          op predicate;
          reason "positive_unit_cost";
          manifest "MethodRequirements/3";
            method_id "term.structural.cost";
            version "1";
            inputs;
              input "cost";
                type {"kind":"rational","context":{"entity":"Operating-beta","book":"legal-beta","case_id":"synthetic-cycle-beta","mode":"synthetic"},"dimensions":{"currency:USD":1,"goods:unit":-1},"scale":"1/1"};
                role state;
                source_ref "Selected cost leaf";
              end;
            end;
            requirements;
              requirement;
                id "positive_cost";
                guard (const {"kind":"boolean","context":{}} true);
                guard_requires [];
                predicate (lt (const {"kind":"rational","context":{"entity":"Operating-beta","book":"legal-beta","case_id":"synthetic-cycle-beta","mode":"synthetic"},"dimensions":{"currency:USD":1,"goods:unit":-1},"scale":"1/1"} "0/1") (ref "cost"));
                requires ["cost"];
                admission_refs [];
                on_false invalid;
                on_unknown unresolved;
              end;
            end;
            required_known [];
            capabilities;
            end;
            residual_prerequisites;
              item "Selected structural cost premise only";
            end;
          end;
          bindings;
            binding "cost";
              kind memory_pointer;
              type {"kind":"rational","context":{"entity":"Operating-beta","book":"legal-beta","case_id":"synthetic-cycle-beta","mode":"synthetic"},"dimensions":{"currency:USD":1,"goods:unit":-1},"scale":"1/1"};
            end;
          end;
        end;
        stage;
          id "migration_fields";
          op record_fields;
          reason "term_migration";
          path ["migration"];
          fields ["source_book_sha256","premise","scope"];
        end;
        stage;
          id "migration_premise";
          op text;
          reason "migration_premise";
          path ["migration","premise"];
          label "migration_premise";
        end;
        stage;
          id "migration_scope";
          op equals;
          reason "migration_scope";
          path ["migration","scope"];
          value "Imported last assessment and initial terms under supplied no-prior-amendment premise";
        end;
      end;
      residuals;
        item "Selected snapshot structural conditions; old internal success label does not grant opening admission";
      end;
    end;
    projections;
      projection "terms" "NestedMapProjection/1";
        context {"entity":"Operating-beta","book":"legal-beta","currency":"USD","case_id":"synthetic-cycle-beta","mode":"synthetic"};
        parent_pointer "/claims";
        child_pointer "/terms";
        fields;
          field "premise";
            kind child_field;
            pointer "/premise";
            type {"kind":"text","context":{}};
          end;
        end;
        residuals;
          item "Supplied structural query fixture; financial validity is separate";
        end;
      end;
    end;
    checks;
      check;
        id "migration_source_digest";
        op sha256_format;
        reason "migration_source_digest";
        path ["migration","source_book_sha256"];
      end;
      check;
        id "term_premises";
        op projected_nonblank_text;
        reason "term_premise";
        projection "terms";
        field "premise";
      end;
    end;
    residuals;
      item "Digest syntax does not establish source availability or migration truth";
    end;
  end;
  semantics "TermStateSemanticBundle/1";
    context {"entity":"Operating-beta","book":"legal-beta","currency":"USD","case_id":"synthetic-cycle-beta","mode":"synthetic"};
    common "BookStateInvariant/1";
      context {"entity":"Operating-beta","book":"legal-beta","currency":"USD","case_id":"synthetic-cycle-beta","mode":"synthetic"};
      definition "MethodCollectionTotals/1";
        method_id "term.common";
        version "1";
        snapshot "MethodCollections/1";
          method_id "term.common";
          version "1";
          inputs;
            input "as_of";
              type {"kind":"date","context":{}};
              role state;
              source_ref "explicit common term-state condition:as_of";
            end;
            input "receivable";
              type {"kind":"rational","context":{"entity":"Operating-beta","book":"legal-beta","case_id":"synthetic-cycle-beta","mode":"synthetic"},"dimensions":{"currency:USD":1},"scale":"1/1"};
              role state;
              source_ref "explicit common term-state condition:receivable";
            end;
          end;
          collections;
            collection "claims";
              fields;
                field "identity";
                  type {"kind":"text","context":{}};
                  role state;
                  source_ref "explicit common term-state condition:identity";
                end;
                field "sale_event";
                  type {"kind":"text","context":{}};
                  role state;
                  source_ref "explicit common term-state condition:sale_event";
                end;
                field "issued";
                  type {"kind":"date","context":{}};
                  role state;
                  source_ref "explicit common term-state condition:issued";
                end;
                field "remaining";
                  type {"kind":"rational","context":{"entity":"Operating-beta","book":"legal-beta","case_id":"synthetic-cycle-beta","mode":"synthetic"},"dimensions":{"currency:USD":1},"scale":"1/1"};
                  role state;
                  source_ref "explicit common term-state condition:remaining";
                end;
              end;
            end;
            collection "seen";
              fields;
                field "id";
                  type {"kind":"text","context":{}};
                  role state;
                  source_ref "explicit common term-state condition:seen";
                end;
              end;
            end;
          end;
          constraints;
            constraint;
              id "claim_ids";
              op unique;
              collection "claims";
              field "identity";
            end;
            constraint;
              id "sale_seen";
              op references;
              source "claims";
              field "sale_event";
              target "seen";
              target_field "id";
            end;
            constraint;
              id "common_rows";
              op each;
              collection "claims";
              definition "MethodRequirements/3";
                method_id "term.common.row";
                version "1";
                inputs;
                  input "remaining";
                    type {"kind":"rational","context":{"entity":"Operating-beta","book":"legal-beta","case_id":"synthetic-cycle-beta","mode":"synthetic"},"dimensions":{"currency:USD":1},"scale":"1/1"};
                    role state;
                    source_ref "explicit common term-state condition:remaining";
                  end;
                  input "issued";
                    type {"kind":"date","context":{}};
                    role state;
                    source_ref "explicit common term-state condition:issued";
                  end;
                  input "as_of";
                    type {"kind":"date","context":{}};
                    role state;
                    source_ref "explicit common term-state condition:as_of";
                  end;
                end;
                requirements;
                  requirement;
                    id "remaining_nonnegative";
                    guard (const {"kind":"boolean","context":{}} true);
                    guard_requires [];
                    predicate (le (const {"kind":"rational","context":{"entity":"Operating-beta","book":"legal-beta","case_id":"synthetic-cycle-beta","mode":"synthetic"},"dimensions":{"currency:USD":1},"scale":"1/1"} "0/1") (ref "remaining"));
                    requires ["remaining"];
                    admission_refs [];
                    on_false invalid;
                    on_unknown unresolved;
                  end;
                  requirement;
                    id "issued_by_book";
                    guard (const {"kind":"boolean","context":{}} true);
                    guard_requires [];
                    predicate (le (ref "issued") (ref "as_of"));
                    requires ["issued","as_of"];
                    admission_refs [];
                    on_false invalid;
                    on_unknown unresolved;
                  end;
                end;
                required_known [];
                capabilities;
                end;
                residual_prerequisites;
                  item "Common claim conditions only";
                end;
              end;
              bindings;
                binding "remaining";
                  scope row;
                  field "remaining";
                end;
                binding "issued";
                  scope row;
                  field "issued";
                end;
                binding "as_of";
                  scope global;
                  field "as_of";
                end;
              end;
            end;
          end;
          residual_prerequisites;
            item "Complete supplied claims only";
          end;
        end;
        assessment "MethodRequirements/3";
          method_id "term.common.total";
          version "1";
          inputs;
            input "total";
              type {"kind":"rational","context":{"entity":"Operating-beta","book":"legal-beta","case_id":"synthetic-cycle-beta","mode":"synthetic"},"dimensions":{"currency:USD":1},"scale":"1/1"};
              role state;
              source_ref "explicit common term-state condition:total";
            end;
            input "receivable";
              type {"kind":"rational","context":{"entity":"Operating-beta","book":"legal-beta","case_id":"synthetic-cycle-beta","mode":"synthetic"},"dimensions":{"currency:USD":1},"scale":"1/1"};
              role state;
              source_ref "explicit common term-state condition:receivable";
            end;
          end;
          requirements;
            requirement;
              id "claim_receivable_sum";
              guard (const {"kind":"boolean","context":{}} true);
              guard_requires [];
              predicate (eq (ref "total") (ref "receivable"));
              requires ["total","receivable"];
              admission_refs [];
              on_false invalid;
              on_unknown unresolved;
            end;
          end;
          required_known [];
          capabilities;
          end;
          residual_prerequisites;
            item "No source/accounting admission";
          end;
        end;
        bindings;
          binding "total";
            kind sum;
            collection "claims";
            field "remaining";
          end;
          binding "receivable";
            kind global;
            input "receivable";
          end;
        end;
        residual_prerequisites;
          item "Historical assessment predicates are separate";
        end;
      end;
      globals;
        global "as_of";
          kind date;
        end;
        global "receivable";
          kind balance;
          account "A493";
        end;
      end;
      collections;
        collection "claims";
          kind memory_map;
          pointer "/claims";
          fields;
            field "identity";
              kind key;
            end;
            field "sale_event";
              kind field;
              pointer "/sale_event";
            end;
            field "issued";
              kind field;
              pointer "/issued";
            end;
            field "remaining";
              kind field;
              pointer "/remaining";
            end;
          end;
        end;
        collection "seen";
          kind seen;
          fields;
            field "id";
              kind value;
            end;
          end;
        end;
      end;
      residual_prerequisites;
        item "Role selection, exact native schema and migration premise remain separate";
      end;
    end;
    clock;
      manifest "MethodRequirements/3";
        method_id "term.clock";
        version "1";
        inputs;
          input "cursor";
            type {"kind":"date","context":{}};
            role state;
            source_ref "explicit book date:cursor";
          end;
          input "end";
            type {"kind":"date","context":{}};
            role state;
            source_ref "explicit book date:end";
          end;
        end;
        requirements;
          requirement;
            id "cursor_period";
            guard (const {"kind":"boolean","context":{}} true);
            guard_requires [];
            predicate (le (ref "cursor") (ref "end"));
            requires ["cursor","end"];
            admission_refs [];
            on_false invalid;
            on_unknown unresolved;
          end;
        end;
        required_known [];
        capabilities;
        end;
        residual_prerequisites;
          item "Date-only native cursor convention";
        end;
      end;
      bindings;
        binding "cursor";
          kind book_field;
          pointer "/memory/collection_clock/cursor";
          type {"kind":"date","context":{}};
        end;
        binding "end";
          kind book_field;
          pointer "/period/end_exclusive";
          type {"kind":"date","context":{}};
        end;
      end;
    end;
    terms "NestedQueryInvariantTemplate/1";
      context {"entity":"Operating-beta","book":"legal-beta","currency":"USD","case_id":"synthetic-cycle-beta","mode":"synthetic"};
      iteration "NestedMapProjection/1";
        context {"entity":"Operating-beta","book":"legal-beta","currency":"USD","case_id":"synthetic-cycle-beta","mode":"synthetic"};
        parent_pointer "/claims";
        child_pointer "/terms";
        fields;
          field "owner";
            kind parent_key;
            type {"kind":"text","context":{}};
          end;
          field "identity";
            kind child_key;
            type {"kind":"text","context":{}};
          end;
          field "parent_issued";
            kind parent_field;
            pointer "/issued";
            type {"kind":"date","context":{}};
          end;
          field "due";
            kind child_field;
            pointer "/due";
            type {"kind":"date","context":{}};
          end;
          field "effective";
            kind child_field;
            pointer "/effective";
            type {"kind":"date","context":{}};
          end;
          field "event_id";
            kind child_field;
            pointer "/event_id";
            type {"kind":"text","context":{}};
          end;
          field "predecessor";
            kind child_field;
            pointer "/predecessor";
            type {"kind":"text","context":{}};
          end;
          field "premise";
            kind child_field;
            pointer "/premise";
            type {"kind":"text","context":{}};
          end;
        end;
        residuals;
          item "Supplied structural query fixture; financial validity is separate";
        end;
      end;
      mode rows;
      captures;
        capture "key";
          kind child_key;
          type {"kind":"text","context":{}};
        end;
        capture "effective";
          kind child_field;
          pointer "/effective";
          type {"kind":"date","context":{}};
        end;
        capture "issued";
          kind parent_field;
          pointer "/issued";
          type {"kind":"date","context":{}};
        end;
        capture "now";
          kind book_field;
          pointer "/date";
          type {"kind":"date","context":{}};
        end;
      end;
      template "QueryGuardedInvariant/1";
        context {"entity":"Operating-beta","book":"legal-beta","currency":"USD","case_id":"synthetic-cycle-beta","mode":"synthetic"};
        manifest "MethodRequirements/3";
          method_id "finite.query.invariant";
          version "1";
          inputs;
            input "has_previous";
              type {"kind":"boolean","context":{}};
              role state;
              source_ref "explicit query binding:has_previous";
            end;
            input "previous_id";
              type {"kind":"text","context":{}};
              role state;
              source_ref "explicit query binding:previous_id";
            end;
            input "identity";
              type {"kind":"text","context":{}};
              role state;
              source_ref "explicit query binding:identity";
            end;
            input "predecessor";
              type {"kind":"text","context":{}};
              role state;
              source_ref "explicit query binding:predecessor";
            end;
            input "effective";
              type {"kind":"date","context":{}};
              role state;
              source_ref "explicit query binding:effective";
            end;
            input "due";
              type {"kind":"date","context":{}};
              role state;
              source_ref "explicit query binding:due";
            end;
          end;
          requirements;
            requirement;
              id "unique_effective_identity";
              guard (const {"kind":"boolean","context":{}} true);
              guard_requires [];
              predicate (eq (ref "identity") (const {"kind":"text","context":{}} "initial"));
              requires ["identity"];
              admission_refs [];
              on_false invalid;
              on_unknown unresolved;
            end;
            requirement;
              id "predecessor_chain";
              guard (ref "has_previous");
              guard_requires ["has_previous"];
              predicate (eq (ref "predecessor") (ref "previous_id"));
              requires ["predecessor","previous_id"];
              admission_refs [];
              on_false invalid;
              on_unknown unresolved;
            end;
            requirement;
              id "initial_sentinel";
              guard (not (ref "has_previous"));
              guard_requires ["has_previous"];
              predicate (eq (ref "predecessor") (const {"kind":"text","context":{}} "none"));
              requires ["predecessor"];
              admission_refs [];
              on_false invalid;
              on_unknown unresolved;
            end;
            requirement;
              id "issued_before_effective";
